<script setup lang="ts">import { nextTick, onMounted, ref } from 'vue'; import { Bot, Send, Paperclip, RotateCcw } from 'lucide-vue-next'; import PageHeader from '../components/PageHeader.vue'; import { useResourcesStore } from '../stores/resources'; import { api } from '../api/client'; import { useAppStore } from '../stores/app'; const resources = useResourcesStore(); const app = useAppStore(); const text = ref(''); const sending = ref(false); const conversation = ref(''); const messages = ref<Array<{ role:'user'|'assistant'; text:string; tools?:string[]}>>([]); const scroller = ref<HTMLElement>(); onMounted(async () => { await resources.loadSources(); const source = resources.sources.find(s => s.enabled); if (!source) app.toast('请先连接一个可用的消息源') }); async function send() { const source = resources.sources.find(s => s.enabled); if (!source || !text.value.trim() || sending.value) return; const prompt = text.value.trim(); text.value = ''; messages.value.push({ role:'user', text:prompt }); sending.value = true; await nextTick(); try { const result = await api.agentChat({ source_id: source.id, conversation_id: conversation.value || undefined, message: prompt }); conversation.value = result.conversation_id; messages.value.push({ role:'assistant', text: result.message, tools: result.tool_activity }); } catch (e) { messages.value.push({ role:'assistant', text: e instanceof Error ? e.message : '助手暂时不可用' }) } finally { sending.value = false; await nextTick(); scroller.value?.scrollTo({ top: scroller.value.scrollHeight, behavior: 'smooth' }) } }</script>
<template><section class="page-content agent-page"><PageHeader eyebrow="CampusCue AI" title="AI 助手" description="用自然语言整理校园事务，助手只会基于已连接的消息源工作。"><button class="button button-secondary" @click="messages = []; conversation = ''"><RotateCcw :size="16" />新对话</button></PageHeader><section class="agent-shell panel"><div ref="scroller" class="chat-scroll"><div v-if="!messages.length" class="agent-welcome"><div class="agent-mark"><Bot :size="25" /></div><h2>今天想先理清什么？</h2><p>可以问我“这周有哪些截止时间”，或描述一条需要跟进的校园事务。</p><div class="prompt-chips"><button @click="text = '帮我梳理这周的截止时间'">梳理这周截止时间</button><button @click="text = '我应该先做什么？'">我应该先做什么？</button></div></div><article v-for="(message, index) in messages" :key="index" class="chat-message" :class="message.role"><div class="chat-avatar"><Bot v-if="message.role === 'assistant'" :size="15" /><span v-else>P</span></div><div class="chat-bubble"><p>{{ message.text }}</p><div v-if="message.tools?.length" class="tool-activity"><span>执行记录</span><small v-for="tool in message.tools" :key="tool">{{ tool }}</small></div></div></article><div v-if="sending" class="chat-message assistant"><div class="chat-avatar"><Bot :size="15" /></div><div class="chat-bubble pending-dots"><i></i><i></i><i></i></div></div></div><form class="chat-composer" @submit.prevent="send"><button type="button" class="icon-button" aria-label="添加附件"><Paperclip :size="18" /></button><label class="sr-only" for="agent-input">对 AI 助手说</label><textarea id="agent-input" v-model="text" :disabled="sending" rows="1" placeholder="描述一件校园事务…" @keydown.enter.exact.prevent="send"></textarea><button class="send-button" :disabled="!text.trim() || sending" aria-label="发送" type="submit"><Send :size="17" /></button></form></section></section></template>
